#!/usr/bin/env python3
"""Run the binary with stdout+stderr on a PTY, capture raw bytes."""
import os, pty, sys, select, subprocess, json, signal, time, errno

def run_pty(args, env_over=None, timeout=90, both=True):
    e = dict(os.environ)
    for k, v in (env_over or {}).items():
        if v is None: e.pop(k, None)
        else: e[k] = v
    mo, so = pty.openpty()
    me, se = pty.openpty()
    p = subprocess.Popen(["/workspace/executable"]+args, stdin=subprocess.DEVNULL,
        stdout=so, stderr=se, env=e, close_fds=True)
    os.close(so); os.close(se)
    out = {mo: b"", me: b""}
    fds = [mo, me]
    t0 = time.time()
    while fds and time.time()-t0 < timeout:
        r,_,_ = select.select(fds, [], [], 0.3)
        for fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                d = b""
            if not d:
                fds.remove(fd)
            else:
                out[fd] += d
        if p.poll() is not None and not r:
            # drain a bit more
            time.sleep(0.2)
            for fd in list(fds):
                try:
                    d = os.read(fd, 65536)
                    if d: out[fd]+=d
                    else: fds.remove(fd)
                except OSError:
                    fds.remove(fd)
            if not any(True for fd in fds):
                break
            break
    try: p.wait(timeout=5)
    except Exception: p.kill()
    for fd in (mo, me):
        try: os.close(fd)
        except Exception: pass
    return p.returncode, out[mo], out[me]

if __name__ == "__main__":
    spec = json.loads(sys.argv[1])
    rc, o, er = run_pty(spec["args"], spec.get("env"), spec.get("timeout", 90))
    print("LABEL:", spec.get("label",""))
    print("ENV:", json.dumps(spec.get("env")))
    print("EXIT:", rc)
    print("PTY-STDOUT:", repr(o))
    print("PTY-STDERR:", repr(er))
    print("has ESC in stderr:", b"\x1b" in er, "| has ESC in stdout:", b"\x1b" in o)
