    def _ereader(self):
        for line in self.p.stderr:
            with self.lock:
                self.err.append(line.decode("utf8", "replace").rstrip("\n"))

    def send(self, obj):
        body = json.dumps(obj, separators=(",", ":")).encode()
        self.p.stdin.write(b"Content-Length: %d\r\n\r\n" % len(body))
        self.p.stdin.write(body)
        self.p.stdin.flush()

    def send_raw(self, data: bytes):
        self.p.stdin.write(data)
        self.p.stdin.flush()

    def wait_id(self, id_, timeout=30):
        end = time.time() + timeout
        while time.time() < end:
            with self.lock:
                for _, _, m in self.msgs:
                    if m.get("id") == id_ and ("result" in m or "error" in m):
                        return m
            time.sleep(0.05)
        return None

    def drain(self):
        with self.lock:
            out = [m for _, _, m in self.msgs]
            self.msgs = []
            return out

    def all(self):
        with self.lock:
            return [m for _, _, m in self.msgs]

    def errs(self):
        with self.lock:
            return list(self.err)

    def close(self, timeout=5):
        try:
            self.p.stdin.close()
        except Exception:
            pass
        try:
            self.p.wait(timeout)
        except Exception:
            self.p.kill()
        return self.p.returncode


def initialize(c, root=None, caps=None, id_=1, extra=None):
    params = {
        "processId": os.getpid(),
        "capabilities": caps if caps is not None else {},
    }
    if root:
        params["rootUri"] = "file://" + os.path.abspath(root)
        params["workspaceFolders"] = [
            {"uri": "file://" + os.path.abspath(root), "name": os.path.basename(root)}
        ]
    if extra:
        params.update(extra)
    c.send({"jsonrpc": "2.0", "id": id_, "method": "initialize", "params": params})
    return c.wait_id(id_)

